package com.travbook.rail.application.usecase;
import com.travbook.rail.application.port.in.DiscoverTrains;
import com.travbook.rail.application.port.out.*;
import com.travbook.rail.domain.model.Rail.*;
import com.travbook.shared.domain.DomainFailure;
import java.time.*;
import java.util.*;
import static com.travbook.shared.domain.DomainFailure.Code.*;
public final class TrainDiscovery implements DiscoverTrains {
    private final RailRepository repository;private final RailGateway suppliers;private final Clock clock;
    public TrainDiscovery(RailRepository repository,RailGateway suppliers,Clock clock){this.repository=repository;this.suppliers=suppliers;this.clock=clock;}
    public List<Station> stations(String q){if(q==null||q.length()>80)throw new DomainFailure(VALIDATION_FAILED,"Station lookup accepts at most 80 characters.");return repository.stations(q.strip());}
    public Page search(Criteria criteria){criteria.validate(clock);var origin=repository.station(criteria.origin()).orElseThrow(()->new DomainFailure(VALIDATION_FAILED,"Select a supported origin station."));var destination=repository.station(criteria.destination()).orElseThrow(()->new DomainFailure(VALIDATION_FAILED,"Select a supported destination station."));Instant now=clock.instant();var result=suppliers.search(criteria,origin,destination,now);if(result.coverage().stream().noneMatch(c->c.available()))throw new DomainFailure(SUPPLIERS_UNAVAILABLE,"Railway providers are unavailable. This is not an empty availability result.");var s=new Snapshot(UUID.randomUUID(),criteria,result.journeys(),result.coverage(),now,now.plusSeconds(900));repository.save(s);return filter(s,0,5,Sort.DEPARTURE,ClassFilter.ALL,StatusFilter.ALL);}
    public Page page(UUID id,int page,int size,Sort sort,ClassFilter travelClass,StatusFilter status){var s=repository.find(id).orElseThrow(()->new DomainFailure(NOT_FOUND,"Train search not found."));s.requireFresh(clock.instant());return filter(s,page,size,sort,travelClass,status);}
    private Page filter(Snapshot s,int page,int size,Sort sort,ClassFilter travelClass,StatusFilter status){if(page<0||page>100||size<1||size>20||sort==null||travelClass==null||status==null)throw new DomainFailure(VALIDATION_FAILED,"Invalid train filters or pagination.");Comparator<Journey> order=sort==Sort.DURATION?Comparator.comparingInt(j->j.durationMinutes()):Comparator.comparing(j->j.departure());var list=s.journeys().stream().filter(j->j.departure().toInstant().isAfter(clock.instant())).filter(j->j.availability().stream().anyMatch(a->(travelClass==ClassFilter.ALL||a.travelClass().name().equals(travelClass.name()))&&(status==StatusFilter.ALL||a.status().name().equals(status.name())))).sorted(order.thenComparing(j->j.id())).toList();return new Page(s,list.stream().skip((long)page*size).limit(size).toList(),list.size(),page,size);}
    public Details journey(UUID id){var s=repository.forJourney(id).orElseThrow(()->new DomainFailure(NOT_FOUND,"Train journey not found."));s.requireFresh(clock.instant());var j=s.journeys().stream().filter(v->v.id().equals(id)).findFirst().orElseThrow();j.requireFuture(clock.instant());return new Details(s,j);}
    public Check availability(UUID id,TravelClass travelClass,Quota quota){if(travelClass==null||quota==null)throw new DomainFailure(VALIDATION_FAILED,"Select a supported class and quota.");var details=journey(id);var j=details.journey();var previous=j.availability().stream().filter(a->a.travelClass()==travelClass).findFirst().orElseThrow(()->new DomainFailure(VALIDATION_FAILED,"Class not offered on this train."));var current=suppliers.availability(j,travelClass,quota,clock.instant());if(current.travelClass()!=travelClass||current.quota()!=quota)throw new DomainFailure(SUPPLIERS_UNAVAILABLE,"Provider returned mismatched class or quota.");Instant expiry=current.validUntil().isBefore(details.snapshot().expiresAt())?current.validUntil():details.snapshot().expiresAt();if(!expiry.isAfter(clock.instant()))throw new DomainFailure(OFFER_EXPIRED,"This railway observation expired. Search again.");current=new Availability(current.travelClass(),current.quota(),current.status(),current.position(),current.base(),current.fees(),current.total(),current.observedAt(),expiry,current.quotaOpensAt(),current.restrictions());return new Check(id,previous,current,previous.differs(current));}
}
